def _SELF006(self, i):
    fault = i["HighWet"] and not i["LowWet"]
    fill = self.state.get("fill", False)
    if fault or i["Inhibit"] or i["HighWet"]:
        fill = False
    elif not i["LowWet"]:
        fill = True
    self.state["fill"] = fill
    return {"Fill": fill, "SensorFault": fault}
